def countCheapestRoutes(grid):
    MOD = 10 ** 9 + 7
    INF = float("inf")
    n = len(grid[0])
    cost = [INF] * n
    ways = [0] * n
    for r, row in enumerate(grid):
        for c in range(n):
            if r == 0 and c == 0:
                cost[0] = row[0]
                ways[0] = 1
                continue
            bc, bw = INF, 0
            if r > 0:
                bc, bw = cost[c], ways[c]
            if c > 0:
                if cost[c - 1] < bc:
                    bc, bw = cost[c - 1], ways[c - 1]
                elif cost[c - 1] == bc:
                    bw += ways[c - 1]
            cost[c] = bc + row[c]
            ways[c] = bw % MOD
    return ways[-1] % MOD
